#include <stdio.h>
#include <time.h>

int main(void) {
  struct tm t = {.tm_year = 73, .tm_mon = 8, .tm_mday = 16, .tm_hour = 1, .tm_min = 3, .tm_sec = 52};
  fputs(asctime(&t), stdout);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  clock_t start = clock();
  volatile double sum = 0;
  for (int i = 0; i < 10000000; i++) sum += i;
  printf("%.3f seconds\n", (double)(clock() - start) / CLOCKS_PER_SEC);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t now = time(NULL);
  fputs(ctime(&now), stdout);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t start = time(NULL);
  time_t later = start + 90;
  printf("%.0f seconds\n", difftime(later, start));
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t now = time(NULL);
  struct tm *utc = gmtime(&now);
  if (utc == NULL) return 1;
  printf("%02d:%02d UTC\n", utc->tm_hour, utc->tm_min);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t now = time(NULL);
  struct tm utc;
  if (gmtime_r(&now, &utc) == NULL) return 1;
  printf("%02d:%02d UTC\n", utc.tm_hour, utc.tm_min);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t now = time(NULL);
  struct tm *local = localtime(&now);
  if (local == NULL) return 1;
  printf("%04d-%02d-%02d\n", local->tm_year + 1900, local->tm_mon + 1, local->tm_mday);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t now = time(NULL);
  struct tm local;
  if (localtime_r(&now, &local) == NULL) return 1;
  printf("%04d-%02d-%02d\n", local.tm_year + 1900, local.tm_mon + 1, local.tm_mday);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  struct tm t = {.tm_year = 2001 - 1900, .tm_mon = 6, .tm_mday = 4, .tm_hour = 12, .tm_isdst = -1};
  if (mktime(&t) == (time_t)(-1)) return 1;
  static const char *const days[] = {"Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday"};
  printf("July 4, 2001 was a %s\n", days[t.tm_wday]);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t now = time(NULL);
  struct tm *local = localtime(&now);
  if (local == NULL) return 1;
  char buf[64];
  if (strftime(buf, sizeof buf, "%Y-%m-%d %H:%M:%S", local) == 0) return 1;
  puts(buf);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  time_t now = time(NULL);
  if (now == (time_t)(-1)) return 1;
  printf("%lld\n", (long long)now);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  struct tm t = {.tm_year = 70, .tm_mday = 2};
  time_t seconds = timegm(&t);
  if (seconds == (time_t)(-1)) return 1;
  printf("%lld\n", (long long)seconds);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  struct timespec ts;
  if (timespec_get(&ts, TIME_UTC) == 0) return 1;
  printf("%lld.%09ld\n", (long long)ts.tv_sec, ts.tv_nsec);
  return 0;
}

#include <stdio.h>
#include <time.h>

int main(void) {
  struct timespec res;
  if (timespec_getres(&res, TIME_UTC) == 0) return 1;
  printf("%lld.%09ld seconds\n", (long long)res.tv_sec, res.tv_nsec);
  return 0;
}
